function [ dx ] = modelo_eq( t_out, x, ws, ks,ts,reg,ns,ne,te,n_s,n_c,ns_a,ts_frozen,points,tal,est,yi,utarg,tstarg,nstarg)
[u] = ver_reg_est1(ws,yi,t_out);
[uref] = ver_reg_est1(ws,yi,t_out);
E1 = -6666.7  ;
E2 = -8333.3  ;
E3 = -11111   ;
k1 = 1.6599e6 ;
k2 = 7.2117e8 ;
k3 = 2.6745e12;
dh1 = -263.8  ;
dh2 = -158.3  ;
dh3 = -226.3  ;
cp = 4.184    ;
cpx = 5554.1  ;
cex = 125.91  ;
Tin = 35      ;
Aref = 9.2903 ;
mref = 2.1052 ;
U = 2.3082e-1 ;
Ma = 100      ;
Mb = 100      ;
Mc = 200      ;
Me = 200      ;
