Mp = 100      ;
roa = 1       ;
rob = 0       ;
roc = 0       ;
roe = 0       ;
rog = 0       ;
rop = 0       ;
tro = 65      ;
Vo = 2        ;
Fscal = 1000  ;

y(1)=(exp(E1/(x(7) + 273.15)));
y(2)=(exp(E2/(x(7) + 273.15)));
y(3)=(exp(E3/(x(7) + 273.15)));

dx(1)=((-x(1)*u(1)/(Fscal*x(8)))-k1*y(1)*x(1)*x(2)                                                                                                                           )*tal;
dx(2)=(((1-x(2))*u(1)/(Fscal*x(8)))-k1*y(1)*x(1)*x(2)- k2*y(2)*x(2)*x(3)                                                                                                     )*tal;
dx(3)=((-x(3)*u(1)/(Fscal*x(8))) + (3319800.0*y(1)*x(1)*x(2)) - (1442340000.0*y(2)*x(2)*x(3)) - 2674500000000.0*y(3)*x(3)*x(6)                                               )*tal;
dx(4)=((-x(4)*u(1)/(Fscal*x(8))) + (1442340000.0*y(2)*x(2)*x(3))                                                                                                             )*tal;
dx(5)=((-x(5)*u(1)/(Fscal*x(8))) + (4011750000000.0*y(3)*x(3)*x(6))                                                                                                          )*tal;
dx(6)=((-x(6)*u(1)/(Fscal*x(8))) + k2*y(2)*x(2)*x(3) - (1337250000000.0*y(3)*x(3)*x(6))                                                                                      )*tal;
dx(7)=(((u(1)*(Tin - x(7)))/(Fscal*x(8)))+ (104656218.9*y(1)*x(1)*x(2)) + (27285184270.0*y(2)*x(2)*x(3)) + (144655676400000.0*y(3)*x(3)*x(6)) - 0.0002434546857*(x(7) - u(2)))*tal;
dx(8)=(u(1)/Fscal                                                                                                                                                            )*tal;
dx(9)=(-cpx*(k2*y(2)*x(2)*x(3) - 0.5*k3*y(3)*x(3)*x(6))*x(8) - cex*(2*k2*y(2)*x(2)*x(3)*x(8))                                                                                )*tal;
dx=transp(dx);
end                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                       
